cd /testbed && python3 - <<'PY' | patch -p1
from pathlib import Path
import difflib
path = Path('axum/src/extract/matched_path.rs')
old = path.read_text()
tests = '''
    #[crate::test]
    async fn cannot_extract_on_fallback() {
        async fn handler(path: Option<MatchedPath>) {
            assert!(path.is_none());
        }

        let app = Router::new()
            .nest("/nested", Router::new().fallback(handler))
            .fallback(handler);
        let client = TestClient::new(app);

        for path in ["/", "/foo", "/nested", "/nested/", "/nested/foo"] {
            let res = client.get(path).send().await;
            assert_eq!(res.status(), StatusCode::OK);
        }
    }

    #[crate::test]
    async fn extracting_on_handler_in_fallback_router() {
        async fn handler(path: MatchedPath) -> String {
            path.as_str().to_owned()
        }

        let inner = Router::new()
            .route("/", get(handler))
            .route("/:a", get(handler));
        let app = Router::new().fallback_service(inner);
        let client = TestClient::new(app);

        let res = client.get("/").send().await;
        assert_eq!(res.status(), StatusCode::OK);
        assert_eq!(res.text().await, "/");

        let res = client.get("/foo").send().await;
        assert_eq!(res.status(), StatusCode::OK);
        assert_eq!(res.text().await, "/:a");
    }
'''
assert old.endswith('}\n')
new = old[:-2] + tests + '}\n'
print(''.join(difflib.unified_diff(old.splitlines(True), new.splitlines(True), fromfile='a/' + str(path), tofile='b/' + str(path))), end='')
PY
