cd /testbed && python3 - <<'PY' | patch -p1
from pathlib import Path
import difflib
changes = {
    'axum/src/extract/matched_path.rs': [
        ('''        let app = Router::new()
            .nest("/nested", Router::new().fallback(handler))
            .fallback(handler);
        let client = TestClient::new(app);

        for path in ["/", "/foo", "/nested", "/nested/", "/nested/foo"] {
            let res = client.get(path).send().await;
            assert_eq!(res.status(), StatusCode::OK);
        }''', '''        let client = TestClient::new(Router::new().fallback(handler));

        for path in ["/", "/foo"] {
            let res = client.get(path).send().await;
            assert_eq!(res.status(), StatusCode::OK);
        }

        let app = Router::new().nest("/nested", Router::new().fallback(handler));
        let client = TestClient::new(app);

        for path in ["/nested/", "/nested/foo"] {
            let res = client.get(path).send().await;
            assert_eq!(res.status(), StatusCode::OK);
        }'''),
    ],
    'axum/src/routing/tests/fallback.rs': [
        ('use tower::ServiceExt;\n', 'use tower::ServiceExt;\nuse tower_http::services::ServeDir;\n'),
        ('''    let static_files = Router::new().nest_service(
        "/",
        get_service(tower_http::services::ServeDir::new(".")),
    );''', '''    let static_files = Router::new().nest_service("/", get_service(ServeDir::new(".")));'''),
    ],
    'axum/src/routing/path_router.rs': [
        ('''    pub(super) fn merge(&mut self, other: PathRouter<S, B, IS_FALLBACK>) -> Result<(), Cow<'static, str>> {''', '''    pub(super) fn merge(
        &mut self,
        other: PathRouter<S, B, IS_FALLBACK>,
    ) -> Result<(), Cow<'static, str>> {'''),
    ],
}
